"""Validate data/incidents.csv against data/schema.md (v0.1). Usage: python tools/validate.py"""
import csv
import sys
from datetime import date
from pathlib import Path

COLUMNS = ["id", "incident_date", "disclosure_date", "disclosed_by", "developer", "model", "category",
           "severity", "fmir_reportable", "latency_days", "sources", "coder", "notes"]
DISCLOSED_BY = {"developer", "third_party_researcher", "press", "user", "regulator"}
CATEGORIES = {"misuse_uplift", "loss_of_control_or_autonomy", "security_breach_or_weights_leak",
              "deceptive_behaviour_in_eval", "harmful_deployment_output", "other"}
REPORTABLE = {"likely", "possible", "unlikely"}


def parse_date(s):
    return date.fromisoformat(s) if s else None


def main(path=Path(__file__).resolve().parent.parent / "data" / "incidents.csv"):
    errors = []
    seen = set()
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames != COLUMNS:
            errors.append(f"header mismatch: {reader.fieldnames}")
        for n, row in enumerate(reader, start=2):
            def err(msg):
                errors.append(f"line {n} ({row.get('id')}): {msg}")
            if row["id"] in seen:
                err("duplicate id")
            seen.add(row["id"])
            try:
                inc, dis = parse_date(row["incident_date"]), parse_date(row["disclosure_date"])
            except ValueError as e:
                err(f"bad date: {e}")
                continue
            if not dis:
                err("disclosure_date required")
            if row["disclosed_by"] not in DISCLOSED_BY:
                err("bad disclosed_by")
            if row["category"] not in CATEGORIES:
                err("bad category")
            if row["severity"] not in {"1", "2", "3", "4"}:
                err("severity must be 1-4")
            if row["fmir_reportable"] not in REPORTABLE:
                err("bad fmir_reportable")
            if inc and dis:
                expected = (dis - inc).days
                if row["latency_days"] and int(row["latency_days"]) != expected:
                    err(f"latency_days should be {expected}")
            if not row["sources"].strip():
                err("at least one source required")
    for e in errors:
        print(e)
    print(f"{len(seen)} rows checked, {len(errors)} problems")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
